B.axQ=s(["\u062c\u062f\u064a\u062f: \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u064a \xab\u0628\u062d\u062b \u0627\u0644\u0641\u062a\u0627\u0648\u0649 \u0645\u0646 \u0643\u062a\u0628 \u0627\u0644\u062b\u0642\u0627\u062a\xbb\u060c \u0648\u0628\u0637\u0627\u0642\u062a\u0647 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.","\u0627\u0644\u0628\u062d\u062b \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0623\u0633\u0631\u0639: \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u062a\u064f\u0628\u062d\u062b \u0645\u0639\u0627\u064b \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f.","\u0625\u0646 \u0644\u0645 \u064a\u0648\u062c\u062f \u0644\u0627\u0628\u0646 \u0639\u062b\u064a\u0645\u064a\u0646 \u0643\u0644\u0627\u0645 \u0641\u064a \u0627\u0644\u0645\u0633\u0623\u0644\u0629\u060c \u064a\u064f\u0628\u062d\u062b \u0639\u0646\u062f \u0628\u0642\u064a\u0629 \u0627\u0644\u0645\u0634\u0627\u064a\u062e \u062c\u0645\u064a\u0639\u0627\u064b \u0648\u064a\u064f\u062e\u062a\u0627\u0631 \u0642\u0648\u0644 \u0634\u064a\u062e \u0648\u0627\u062d\u062f \u0647\u0648 \u0627\u0644\u0623\u0642\u0631\u0628 \u0644\u0644\u0633\u0624\u0627\u0644.","\u0633\u062c\u0644 \u0644\u0644\u0628\u062d\u062b \u0628\u0627\u0644\u0630\u0643\u0627\u0621: \u0632\u0631 \u0627\u0644\u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u064a\u0639\u0631\u0636 \u0645\u062d\u0627\u062f\u062b\u0627\u062a\u0643 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0648\u0647\u064a \u0645\u062d\u0641\u0648\u0638\u0629 \u0639\u0644\u0649 \u0647\u0627\u062a\u0641\u0643.","\u0623\u0636\u064a\u0641 \u0625\u0644\u0649 \xab\u0627\u0644\u0645\u0634\u0627\u064a\u062e \u0627\u0644\u062b\u0642\u0627\u062a\xbb: \u0645\u0642\u0628\u0644 \u0627\u0644\u0648\u0627\u062f\u0639\u064a \u0648\u064a\u062d\u064a\u0649 \u0627\u0644\u062d\u062c\u0648\u0631\u064a.","\xab\u0627\u0633\u0623\u0644 \u0627\u0644\u0634\u064a\u062e\xbb: \u0644\u0643\u0644 \u0633\u0627\u0626\u0644 \u0631\u0642\u0645 \u062b\u0627\u0628\u062a \u064a\u0638\u0647\u0631 \u0644\u0644\u0634\u064a\u062e\u060c \u0648\u0645\u062d\u0627\u062f\u062b\u0629 \u062e\u0627\u0635\u0629 \u062a\u062c\u0645\u0639 \u0623\u0633\u0626\u0644\u062a\u0647\u060c \u0648\u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0634\u064a\u062e \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0628\u0646\u062c\u0645\u0629 \u0623\u0648 \u062a\u062b\u0628\u064a\u062a\u0647\u0627."],t.s)
B.b3M=new A.a_("3.6.0",B.axQ)
B.aQq=s(["\xab\u0628\u062d\u062b \u0627\u0644\u0641\u062a\u0627\u0648\u0649 \u0645\u0646 \u0643\u062a\u0628 \u0627\u0644\u062b\u0642\u0627\u062a\xbb \u0641\u064a \u062a\u0637\u0628\u064a\u0642 \u0623\u0646\u062f\u0631\u0648\u064a\u062f: \u0627\u0643\u062a\u0628 \u0633\u0624\u0627\u0644\u0643 \u0643\u0645\u0627 \u062a\u0631\u064a\u062f\u060c \u0641\u064a\u064f\u0642\u0633\u064e\u0651\u0645 \u0625\u0644\u0649 \u0645\u0633\u0627\u0626\u0644\u0647\u060c \u0648\u064a\u064f\u0628\u062d\u062b \u0644\u0643\u0644 \u0645\u0633\u0623\u0644\u0629 \u0639\u0646\u062f \u0627\u0628\u0646 \u0639\u062b\u064a\u0645\u064a\u0646 \u062b\u0645 \u0645\u0646 \u0628\u0639\u062f\u0647.","\u062e\u0644\u0627\u0635\u0629 \u0645\u062e\u062a\u0635\u0631\u0629 \u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0634\u064a\u062e \u0641\u064a \u0643\u0644 \u0645\u0633\u0623\u0644\u0629\u060c \u0645\u0628\u0646\u064a\u0629 \u0639\u0644\u0649 \u0646\u0635\u0648\u0635\u0647 \u0627\u0644\u0645\u0646\u0642\u0648\u0644\u0629 \u0648\u062d\u062f\u0647\u0627\u060c \u0648\u062a\u062d\u062a\u0647\u0627 \u0627\u0644\u0646\u0635 \u0628\u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0635\u0641\u062d\u0629.","\u0632\u0631 \xab\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u062e\u0637\u0623 \u0641\u064a \u0627\u0644\u062a\u0644\u062e\u064a\u0635\xbb\u060c \u0648\u0644\u0644\u0645\u0634\u0631\u0641\u064a\u0646 \u0632\u0631\u0651\u0627\u0646 \u0644\u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0630\u0643\u0627\u0621 \u0623\u0648 \u0627\u0644\u062e\u0644\u0627\u0635\u0629."],t.s)
