B.aAE=s(["\u0627\u0643\u062a\u0628 \u0633\u0624\u0627\u0644\u0643 \u0628\u0643\u0644\u0627\u0645\u0643 \u0627\u0644\u0639\u0627\u062f\u064a\u060c \u0641\u064a\u0639\u0631\u0636 \u0644\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0642\u0631\u0628 \u0643\u0644\u0627\u0645 \u0627\u0644\u0634\u064a\u062e \u0625\u0644\u064a\u0647 \u0628\u0646\u0635\u0651\u0647.","\u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0635\u0648\u062a\u064a: \u0627\u0636\u063a\u0637 \u0627\u0644\u0645\u064a\u0643\u0631\u0648\u0641\u0648\u0646 \u0648\u0642\u0644 \u0633\u0624\u0627\u0644\u0643.","\xab\u0627\u0642\u0631\u0623 \u0644\u064a\xbb: \u064a\u0642\u0631\u0623 \u0644\u0643 \u0627\u0644\u062c\u0648\u0627\u0628 \u0628\u0635\u0648\u062a \u0627\u0644\u0647\u0627\u062a\u0641.","\u0627\u0644\u0648\u0650\u0631\u062f \u0627\u0644\u064a\u0648\u0645\u064a \u0645\u0646 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0645\u0639 \u0639\u062f\u062f \u0623\u064a\u0627\u0645\u0643 \u0627\u0644\u0645\u062a\u062a\u0627\u0644\u064a\u0629.","\u0645\u0644\u0627\u062d\u0638\u0627\u062a\u0643 \u0627\u0644\u062e\u0627\u0635\u0629 \u0639\u0644\u0649 \u0623\u064a \u062c\u0648\u0627\u0628.","\u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0647\u062c\u0631\u064a\u060c \u0648\xab\u0623\u064f\u0636\u064a\u0641 \u062d\u062f\u064a\u062b\u0627\u064b\xbb \u0641\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.","\u0632\u0631 \xab\u0627\u0644\u062e\u0637 \u0627\u0644\u0643\u0628\u064a\u0631\xbb \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a.","\u0645\u0646\u0634\u0648\u0631\u0627\u062a \u0627\u0644\u0634\u064a\u062e \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u062a\u0635\u0644 \u0643\u0644 \u064a\u0648\u0645 \u062f\u0648\u0646 \u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062a\u0637\u0628\u064a\u0642.","\u0635\u0646\u062f\u0648\u0642 \xab\u0627\u0642\u062a\u0631\u0627\u062d \u0644\u0644\u0645\u0637\u0648\u0651\u0631\xbb \u0641\u064a \u0635\u0641\u062d\u0629 \u0627\u0644\u0645\u0632\u064a\u062f."],t.s)
B.b5p=new A.a_("2.0.0",B.aAE)
